    {"교리":"하나님의 전능하심", "설명":"땅의 높은 곳을 밟으시는 것은 모든 높아진 것들이 하나님 앞에 굴복함을 의미", "관련구절":"사 40:12, 나 1:3-5, 시 104:32"},
    {"교리":"역사의 주권", "설명":"역사적 사건들이 하나님의 주권적 심판의 도구로 사용됨", "관련구절":"사 10:5, 렘 25:9, 단 4:34-35"}
