    {"상황":"삶의 기반이 무너져서 의미를 잃은 성도", "성경원리":"모든 것이 무너져도 하나님은 남으심. 폐허 위에 새 포도원이 가능함", "실제적용":"현재 상황을 하나님의 새로운 역사의 시작점으로 바라보는 믿음을 훈련하라"}
