    {"항목":"음행의 값 비유", "내용":"우상 숭배를 영적 음행으로 비유하는 것은 호세아에서도 사용됨. 경제적 수탈과 영적 배도의 결합", "목회적활용":"물질적 탐욕과 영적 배도는 연결되어 있음"},
    {"항목":"앗수르 약탈", "내용":"앗수르는 정복지의 신상들과 금은보화를 약탈하는 관행이 있었음. 이것이 기생의 값으로 돌아가는 심판의 역사적 성취", "목회적활용":"죄의 결과는 역사적으로 구체적으로 나타남"}
