    {"교리":"영적 음행론", "설명":"우상 숭배를 음행에 비유하는 것은 하나님과 이스라엘의 관계가 결혼 언약임을 전제. 우상 숭배는 간음", "관련구절":"호 1:2, 겔 16:15, 약 4:4"},
    {"교리":"심판의 공의성", "설명":"기생의 값으로 모은 것이 기생의 값으로 돌아감. 죄에 상응하는 공의로운 심판", "관련구절":"갈 6:7, 잠 26:27, 옵 1:15"}
