    {"원어":"תַּנִּים (탄님)", "의미_문법":"들개, 자칼 - 광야의 구슬픈 울음소리를 내는 동물", "설교포인트":"선지자의 슬픔이 동물의 애절한 울음에 비유됨"},
    {"원어":"בְּנוֹת יַעֲנָה (베노트 야아나)", "의미_문법":"타조의 딸들 - 타조의 울음소리는 매우 처량함", "설교포인트":"심판의 슬픔은 말로 표현할 수 없을 만큼 깊음"}
