    {"원어":"רָע (라)", "의미_문법":"재앙, 악 - 심판의 결과로 오는 재난", "설교포인트":"죄의 결과로 오는 재앙은 여호와로부터 옴"},
    {"원어":"שַׁעַר יְרוּשָׁלִַם (샤아르 예루살람)", "의미_문법":"예루살렘 성문 - 도시의 중심, 공적 삶의 장소", "설교포인트":"심판은 주변부에서 시작하여 중심부까지 미침"}
