    {"원어":"מוֹצָאֹתָיו מִקֶּדֶם מִימֵי עוֹלָם (모차오타이브 미케뎀 미메이 올람)", "의미_문법":"그의 근본은 상고에 영원에 있다 - 메시아의 선재성, 영원성", "설교포인트":"메시아는 인간을 초월한 영원한 존재"}
