    {"원어":"שִׁבְעָה רֹעִים (쉬브아 로임)", "의미_문법":"일곱 목자 - 완전수, 충분한 지도자들", "설교포인트":"메시아 아래 충분한 지도자들이 세워짐"},
    {"원어":"שְׁמֹנָה נְסִיכֵי (쉐모나 네시케이)", "의미_문법":"여덟 군왕 - 넘치는 지도자들, 충분한 군사적 능력", "설교포인트":"메시아의 나라는 완전하게 갖추어짐"}
