    {"원어":"מַעֲשֵׂה בֵית-אַחְאָב (마아세 베이트 아흐압)", "의미_문법":"아합 집의 행위들, 모든 행실", "설교포인트":"가장 악한 왕들의 행위를 따름"},
    {"원어":"שְׁמָמָה (쉬마마)", "의미_문법":"황폐하게 하다, 공포의 대상이 되다", "설교포인트":"완전한 황폐가 심판의 결과"},
    {"원어":"חֶרְפַּת עַמִּי (헤르파트 암미)", "의미_문법":"내 백성의 비방, 내 백성의 수치", "설교포인트":"하나님의 백성이라 불리는 것이 오히려 수치가 됨"}
